import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def solve_diophantine(N):
    factors = []
    # Find all factors of N
    for i in range(1, int(math.sqrt(N)) + 1):
        if N % i == 0:
            factors.append((i, N // i))

    solutions = []

    for A, B in factors:
        if A == B:
            continue

        # A = p2 - p1, B = p2 + p1. We need A < B for positive p1.
        if A > B:
            continue

        # A and B must have the same parity. Since N=735 is odd, A and B must both be odd.
        if (A + B) % 2 != 0:
            continue

        p2 = (A + B) // 2
        p1 = (B - A) // 2

        if p1 <= 0: # Should not happen if A < B and A, B > 0
            continue

        if is_prime(p1) and is_prime(p2):
            solutions.append((p1, p2))

    return solutions

N = 735
solutions = solve_diophantine(N)
print(f"Solutions (p1, p2): {solutions}")

